namespace {
const std::string identity="0123456789abcdef0123456789abcdef";
void check(bool yes,const std::string& why){if(!yes)throw std::runtime_error(why);}
template<class F>void error(const std::string& code,F f){try{f();}catch(const DbError& e){check(e.code==code,"expected "+code+", got "+e.code+": "+e.what());return;}throw std::runtime_error("missing "+code);}
std::uint64_t value(const a::Page& page){std::uint64_t n=0;for(int i=7;i>=0;--i)n=(n<<8)|page[64+i];return n;}
a::Page image(std::uint64_t id,std::uint64_t v){auto codec=a::default_page_codec();auto p=codec.empty(id);for(unsigned n=0;n<8;++n)p[64+n]=static_cast<unsigned char>(v>>(n*8));codec.stamp(p,0);return p;}
auto device(const fs::path& dir){fs::create_directories(dir);return a::open_native_data_device((dir/"data.pages").u8string());}
std::uint64_t disk_value(DataDevice& data,std::uint64_t id){a::Page p{};if(data.size()<(id+1)*a::page_size)return 0;data.read(id*a::page_size,p.data(),p.size());return value(p);}
json snapshot(const fs::path& dir){auto data=device(dir);a::Options opts;opts.buffer_frames=1;a::Manager manager(dir.u8string(),*data,identity,a::default_page_codec(),opts);json values=json::object();for(auto id:{1,2,3})values[std::to_string(id)]=value(manager.read(0,id));return {{"status","PASS"},{"values",values},{"diagnostics",manager.diagnostics()},{"wal",manager.wal_records()}};}
void seed(const fs::path& dir){auto data=device(dir);a::Options opts;opts.buffer_frames=4;a::Manager manager(dir.u8string(),*data,identity,a::default_page_codec(),opts);manager.begin(1);for(auto id:{1,2,3})manager.update(1,id,image(id,id*10));manager.commit(1);manager.flush_all();manager.checkpoint_fuzzy();}
void marker(const fs::path& dir,const json& j){std::ofstream out(dir/"ready.json",std::ios::binary);out<<j.dump();out.flush();check(bool(out),"marker write failed");out.close();std::cout<<"READY "<<j.dump()<<std::endl;std::this_thread::sleep_for(20s);throw std::runtime_error("parent did not terminate worker within bounded20s");}
void worker(const std::string& scenario,const fs::path& dir){auto data=device(dir);a::Options opts;opts.buffer_frames=scenario=="committed_redo"?32:1;a::Manager manager(dir.u8string(),*data,identity,a::default_page_codec(),opts);
 if(scenario=="committed_redo"){manager.begin(100);manager.update(100,1,image(1,11));manager.update(100,2,image(2,22));manager.update(100,1,image(1,12));manager.update(100,3,image(3,33));manager.update(100,1,image(1,13));auto result=manager.commit(100);marker(dir,{{"scenario",scenario},{"commit",result},{"disk1",disk_value(*data,1)},{"diagnostics",manager.diagnostics()}});}
 else if(scenario=="dirty_loser"){manager.begin(100);manager.update(100,1,image(1,99));manager.update(100,2,image(2,88));manager.update(100,1,image(1,77));marker(dir,{{"scenario",scenario},{"disk1",disk_value(*data,1)},{"disk2",disk_value(*data,2)},{"diagnostics",manager.diagnostics()}});}
 else if(scenario=="active_checkpoint"){manager.begin(100);manager.update(100,1,image(1,66));manager.update(100,2,image(2,55));auto result=manager.checkpoint_fuzzy();marker(dir,{{"scenario",scenario},{"checkpoint",result},{"diagnostics",manager.diagnostics()}});}
 else throw std::runtime_error("unknown worker scenario");
}
json units(const fs::path& root){json checks=json::array();
 {auto dir=root/"basic";auto data=device(dir);a::Options opts;opts.buffer_frames=2;{a::Manager m(dir.u8string(),*data,identity,a::default_page_codec(),opts);m.begin(1);m.update(1,1,image(1,10));m.update(1,2,image(2,20));auto committed=m.commit(1);check(committed["status"]=="COMMITTED"&&data->size()==0,"no-force commit unexpectedly wrote user pages");check(value(m.read(0,1))==10,"buffer committed value");m.flush_all();m.begin(2);m.update(2,1,image(1,11));m.begin(3);error("ARIES_LOCK_REQUIRED",[&]{m.read(3,1);});error("ARIES_PAGE_CONFLICT",[&]{m.update(3,1,image(1,999));});m.abort(3);m.savepoint(2,"s");m.update(2,1,image(1,12));m.update(2,2,image(2,22));m.rollback_to(2,"s");check(value(m.read(2,1))==11&&value(m.read(2,2))==20,"real CLR rollback_to results");m.commit(2);m.flush_all();auto log=m.wal_records();std::size_t clrs=0;for(const auto& r:log["records"])if(r["type"]=="CLR"){++clrs;check(r["undo_next_lsn"].get<std::uint64_t>()<r["lsn"].get<std::uint64_t>(),"CLR invalid next pointer");}check(clrs==2,"rollback_to did not write exactly2 CLRs");checks.push_back({{"case","no_force_owners_savepoint_CLR"},{"status","PASS"},{"clrs",clrs}});}a::Manager reopened(dir.u8string(),*data,identity,a::default_page_codec(),opts);check(value(reopened.read(0,1))==11&&value(reopened.read(0,2))==20,"reopen committed CLR state");}
 {auto dir=root/"no-steal";auto data=device(dir);a::Options opts;opts.buffer_frames=1;opts.steal=false;opts.force_at_commit=true;a::Manager m(dir.u8string(),*data,identity,a::default_page_codec(),opts);m.begin(1);m.update(1,1,image(1,10));error("BUFFER_BUSY",[&]{m.update(1,2,image(2,20));});error("BUFFER_BUSY",[&]{m.flush_page(1);});m.abort(1);m.flush_all();check(value(m.read(0,1))==0,"abort must physically compensate old value");m.begin(2);m.update(2,2,image(2,20));m.commit(2);check(disk_value(*data,2)==20&&m.diagnostics()["steal_flushes"]==0,"force/no-steal policy not real");checks.push_back({{"case","real_no_steal_and_force_policy"},{"status","PASS"}});}
 {auto dir=root/"fuzzy";auto data=device(dir);a::Manager* pointer=nullptr;a::Options opts;opts.buffer_frames=1;opts.checkpoint_interleave=[&]{auto task=std::async(std::launch::async,[&]{pointer->update(100,2,image(2,22));});check(task.wait_for(2s)==std::future_status::ready,"fuzzy checkpoint blocked real transaction update");task.get();};a::Manager m(dir.u8string(),*data,identity,a::default_page_codec(),opts);pointer=&m;m.begin(100);m.update(100,1,image(1,11));auto checkpoint=m.checkpoint_fuzzy();check(checkpoint["active_transactions"]==1&&!checkpoint["data_pages_forced"].get<bool>(),"checkpoint waited for transaction or forced all pages");auto log=m.wal_records();bool middle_update=false;auto begin=checkpoint["begin_lsn"].get<std::uint64_t>(),end=checkpoint["end_lsn"].get<std::uint64_t>();for(const auto& r:log["records"])if(r["type"]=="UPDATE"&&r["lsn"].get<std::uint64_t>()>begin&&r["lsn"].get<std::uint64_t>()<end)middle_update=true;check(middle_update&&disk_value(*data,1)==11,"no real update/steal between checkpoint records");m.abort(100);m.flush_all();checks.push_back({{"case","fuzzy_checkpoint_real_interleaved_active_update"},{"status","PASS"},{"checkpoint",checkpoint}});}
 {auto dir=root/"reserve";auto data=device(dir);a::Options opts;opts.buffer_frames=2;opts.wal_limit_bytes=65536;a::Manager m(dir.u8string(),*data,identity,a::default_page_codec(),opts);m.begin(1);m.update(1,1,image(1,7));auto before=m.diagnostics()["last_lsn"];error("ARIES_LOG_LIMIT",[&]{m.update(1,1,image(1,8));});check(m.diagnostics()["last_lsn"]==before&&value(m.read(1,1))==7,"budget failure mutated page/log");m.abort(1);m.flush_all();check(value(m.read(0,1))==0,"reserved undo space unavailable");checks.push_back({{"case","online_budget_reserves_terminal_and_crash_undo_space"},{"status","PASS"}});}
 {auto dir=root/"readonly";auto data=device(dir);a::Manager m(dir.u8string(),*data,identity);m.begin(1,true);error("READ_ONLY_TRANSACTION",[&]{m.update(1,1,image(1,10));});m.commit(1);check(m.diagnostics()["last_lsn"]==0,"read-only transaction created WAL updates");m.begin(2);for(int n=0;n<64;++n)m.savepoint(2,"s"+std::to_string(n));error("SAVEPOINT_LIMIT",[&]{m.savepoint(2,"overflow");});m.release_savepoint(2,"s32");m.savepoint(2,"allowed");m.abort(2);checks.push_back({{"case","read_only_and_bounded_savepoints"},{"status","PASS"}});}
 {json failures=json::array();for(const auto* point:{"before_wal_write","before_wal_sync","before_durable_control_write","before_data_write","before_data_sync"}){auto dir=root/point;auto data=device(dir);bool armed=false;std::string target=point;{a::Options opts;opts.io_fault=[&](const char* at){if(armed&&target==at){armed=false;throw DbError("IO_ERROR","controlled native persistence failure at "+target);}};a::Manager m(dir.u8string(),*data,identity,a::default_page_codec(),opts);m.begin(1);m.update(1,1,image(1,10));m.commit(1);m.flush_all();m.begin(2);m.update(2,1,image(1,20));const bool data_failure=target=="before_data_write"||target=="before_data_sync";if(data_failure)m.commit(2);armed=true;error("IO_ERROR",[&]{if(data_failure)m.flush_all();else m.commit(2);});check(m.diagnostics()["recovery_required"],"I/O failure did not enter fail-stop");error("RECOVERY_REQUIRED",[&]{m.begin(3);});error("RECOVERY_REQUIRED",[&]{m.commit(2);});}a::Manager restarted(dir.u8string(),*data,identity);auto expected=target=="before_wal_write"?10:20;check(value(restarted.read(0,1))==static_cast<std::uint64_t>(expected),"I/O restart did not honor complete WAL outcome");failures.push_back({{"point",target},{"status","PASS"},{"restart_value",expected},{"commit_failure_outcome","No success returned; complete COMMIT is resolved only by restart"}});}checks.push_back({{"case","five_native_IO_failure_failstop_and_restart"},{"status","PASS"},{"failures",failures}});}
 {auto dir=root/"atomic-first-update-budget";auto data=device(dir);a::Options opts;opts.buffer_frames=2;opts.wal_limit_bytes=65536;a::Manager m(dir.u8string(),*data,identity,a::default_page_codec(),opts);m.begin(1);m.update(1,1,image(1,7));const auto lsn=m.diagnostics()["last_lsn"];for(int n=2;n<=202;++n){m.begin(n);error("ARIES_LOG_LIMIT",[&]{m.update(n,n,image(n,9));});m.abort(n);}check(m.diagnostics()["last_lsn"]==lsn,"failed first updates stranded BEGIN records and consumed undo reserve");m.abort(1);m.flush_all();check(value(m.read(0,1))==0,"terminal reserve exhausted after failed first updates");checks.push_back({{"case","atomic_BEGIN_plus_first_UPDATE_reservation_201_rejections"},{"status","PASS"}});}
 {auto dir=root/"constant-time-metrics";auto data=device(dir);a::Manager m(dir.u8string(),*data,identity);m.begin(1);m.update(1,1,image(1,10));auto stats=m.transaction_metrics(1);std::uint64_t expected=0;auto log=m.wal_records();for(const auto& r:log["records"])if(r["tx"]==1)expected+=80+r["payload_bytes"].get<std::uint64_t>();check(stats["wal_bytes"]==expected&&stats["dirty_pages"]==1,"transaction metrics not bound to actual WAL/DPT");m.flush_page(1);check(m.transaction_metrics(1)["dirty_pages"]==0,"steal flush did not clear this transaction's actual dirty count");auto result=m.commit(1);check(result["dirty_pages"]==0&&result["wal_bytes"]==expected+160,"commit metric lost COMMIT/END bytes");checks.push_back({{"case","actual_transaction_WAL_and_dirty_page_metrics"},{"status","PASS"}});}
#ifdef _WIN32
 {auto dir=root/"control-sharing-transient";auto data=device(dir);bool armed=false;std::future<void> release;
  a::Options opts;opts.io_fault=[&](const char* point){if(armed&&std::string(point)=="before_durable_control_write"){
    armed=false;auto handle=CreateFileW((dir/"control-aries-durable.json").c_str(),GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);check(handle!=INVALID_HANDLE_VALUE,"open deterministic control reader");
    release=std::async(std::launch::async,[handle]{std::this_thread::sleep_for(150ms);CloseHandle(handle);});
  }};
  {a::Manager m(dir.u8string(),*data,identity,a::default_page_codec(),opts);m.begin(1);m.update(1,1,image(1,10));armed=true;auto result=m.commit(1);if(release.valid())release.get();check(result["status"]=="COMMITTED"&&!m.diagnostics()["recovery_required"].get<bool>(),"transient control sharing incorrectly fail-stopped");}
  a::Manager restored(dir.u8string(),*data,identity);check(value(restored.read(0,1))==10,"retried durable control does not survive reopen");checks.push_back({{"case","bounded_control_replace_retries_actual_Windows_sharing_then_reopens"},{"status","PASS"}});
 }
 {auto dir=root/"control-sharing-persistent";auto data=device(dir);HANDLE held=INVALID_HANDLE_VALUE;bool armed=false;
  a::Options opts;opts.io_fault=[&](const char* point){if(armed&&std::string(point)=="before_durable_control_write"){
   armed=false;held=CreateFileW((dir/"control-aries-durable.json").c_str(),GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);check(held!=INVALID_HANDLE_VALUE,"open persistent control reader");}};
  {a::Manager m(dir.u8string(),*data,identity,a::default_page_codec(),opts);m.begin(1);m.update(1,1,image(1,20));armed=true;const auto start=std::chrono::steady_clock::now();error("IO_ERROR",[&]{m.commit(1);});check(std::chrono::steady_clock::now()-start<5s,"control retry failed to remain bounded");if(held!=INVALID_HANDLE_VALUE){CloseHandle(held);held=INVALID_HANDLE_VALUE;}check(m.diagnostics()["recovery_required"],"persistent control replacement failure did not fail-stop");error("RECOVERY_REQUIRED",[&]{m.begin(2);});}
  a::Manager restored(dir.u8string(),*data,identity);check(value(restored.read(0,1))==20,"complete unacknowledged COMMIT must be resolved at recovery");checks.push_back({{"case","persistent_control_sharing_fails_closed_and_complete_unknown_commit_recovers"},{"status","PASS"}});
 }
#endif
 return {{"status","PASS"},{"checks",checks},{"scope","Native Windows file persistence; integrated Engine SQL is validated by the separate aries_sql suite"}};
}
}
int main(int argc,char** argv){try{if(argc==1){auto root=fs::absolute(fs::path("aries_test-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count())));if(fs::exists(root))throw std::runtime_error("test directory already exists");fs::create_directories(root);std::cout<<units(root).dump(2)<<"\n";return 0;}if(argc<3)throw std::runtime_error("usage --unit|--seed|--snapshot DIR or --worker SCENARIO DIR");auto command=std::string(argv[1]);if(command=="--unit"){auto result=units(fs::u8path(argv[2]));std::cout<<result.dump(2)<<"\n";return 0;}if(command=="--seed"){seed(fs::u8path(argv[2]));std::cout<<"{\"status\":\"PASS_SEED\"}\n";return 0;}if(command=="--snapshot"){auto result=snapshot(fs::u8path(argv[2]));std::cout<<result.dump(2)<<"\n";return 0;}if(command=="--worker"&&argc==4){worker(argv[2],fs::u8path(argv[3]));return 2;}throw std::runtime_error("invalid command");}catch(const DbError& e){std::cerr<<json{{"status","ERROR"},{"code",e.code},{"message",e.what()}}.dump()<<"\n";return 4;}catch(const std::exception& e){std::cerr<<json{{"status","FAIL"},{"message",e.what()}}.dump()<<"\n";return 5;}}
